{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4-8",
      "explanation": "The method concatenates the user-supplied searchKey directly into a SOQL string, allowing an attacker to inject arbitrary SOQL clauses and potentially access or modify data beyond their permissions.",
      "remediation": "Rewrite the query to use bind variables, e.g., 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :('%' + String.escapeSingleQuotes(searchKey) + '%') LIMIT 50', or use Database.queryWithBinds. This prevents injection by treating user input as a value rather than executable code."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-level security not enforced",
      "severity": "Medium",
      "file": "InvoiceSearchController.cls",
      "lines": "searchInvoices method",
      "explanation": "The method returns Invoice__c fields (Amount__c, Status__c) without checking field-level read permissions, allowing users to see data they may not be authorized to view.",
      "remediation": "Enforce FLS by using Security.stripInaccessible, WITH SECURITY_ENFORCED, or explicitly checking field permissions before returning data."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query",
      "severity": "High",
      "file": "ReportFilterController.cls",
      "lines": "6-12",
      "explanation": "The method concatenates user-supplied field names and values directly into a SOQL string without validation or escaping, allowing an attacker to inject arbitrary SOQL clauses and potentially read or manipulate data beyond intended scope.",
      "remediation": "Replace the dynamic query construction with bind variables or a whitelist of allowed fields. For example, parse each filter, validate the field name against an allow-list, and use a bind variable for the value: `WHERE fieldName = :value`. Alternatively, use Database.queryWithBinds or String.escapeSingleQuotes for any remaining dynamic parts."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Violation on Returned Record",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4-10",
      "explanation": "The method returns the entire Contact record, which includes fields (Email, Birthdate) that the user may not have read permission for, exposing sensitive data.",
      "remediation": "Return only the fields that the user is allowed to read, or enforce field-level security using Security.stripInaccessible or by selecting only permitted fields."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Violation: AnnualRevenue Access",
      "severity": "Medium",
      "file": "AccountRatingService.cls",
      "lines": "4-12",
      "explanation": "The method queries the AnnualRevenue field without enforcing field‑level security, allowing users who lack read permission on AnnualRevenue to view it. This violates CRUD/FLS rules and can expose sensitive data.",
      "remediation": "Enforce FLS by adding WITH USER_MODE to the SOQL query, using Security.stripInaccessible, or removing AnnualRevenue from the query and using a custom permission or field that is allowed for the role."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violation on Task creation",
      "severity": "Medium",
      "file": "CaseEscalationService.cls",
      "lines": "Task t = new Task(...); insert t;",
      "explanation": "The method inserts a Task record without verifying that the running user has create permission on Task. The DmlException is swallowed, hiding the FLS violation from the caller and potentially allowing unsupported data creation or silent failures.",
      "remediation": "Add an FLS check before insertion, e.g., if (Schema.sObjectType.Task.isCreateable()) { insert t; } else { /* handle lack of permission */ }. Alternatively, remove the insert or grant the necessary create permission to the permission set."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing not enforced",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "public without sharing class CaseHistoryController",
      "explanation": "The class is declared without sharing, so the SOQL query ignores record‑level sharing rules and can return cases that the user should not see, even though object and field permissions are checked.",
      "remediation": "Declare the class with sharing (or inherited sharing) or add WITH USER_MODE to the SOQL query to enforce sharing rules for authenticated users."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass",
      "severity": "High",
      "file": "FinancialDashboardController.cls",
      "lines": "1-10",
      "explanation": "The class is declared without sharing, so the @AuraEnabled method returns all Opportunity records regardless of the caller's sharing rules. Partner community users can see opportunities from all accounts, violating record-level security.",
      "remediation": "Declare the class with sharing or inherited sharing, or add a WITH SECURITY_ENFORCED clause to the SOQL query to enforce sharing rules."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Bypassed Record-Level Sharing",
      "severity": "Medium",
      "file": "DataAggregator.cls",
      "lines": "1-20",
      "explanation": "The Apex class is declared \"without sharing\", so all SOQL queries run in system mode and ignore record‑level sharing rules. The @AuraEnabled method returns Lead records, including the Email field, without enforcing sharing, allowing any user with access to the class to view leads they should not see.",
      "remediation": "Declare the class with the \"with sharing\" keyword (or use WITH SECURITY_ENFORCED in SOQL) so that sharing rules are respected. Ensure that any @AuraEnabled entry points run in a sharing context to prevent unauthorized data exposure."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permissions in Permission Set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "12-30",
      "explanation": "The permission set grants ModifyAllData, ViewAllData, and AuthorApex, which give users full access to all data and the ability to author Apex code. This far exceeds the intended purpose of allowing tier‑1 support agents to view and close cases.",
      "remediation": "Remove the ModifyAllData, ViewAllData, and AuthorApex permissions from the permission set. Grant only the necessary object permissions (Case read/edit) and the ApiEnabled permission if needed for API access."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permission Set Privilege",
      "severity": "Medium",
      "file": "Accounts_Payable_Clerk.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants the ManageInternalUsers system permission, which allows users to manage internal users. This is unnecessary for accounts payable clerks and provides a privilege escalation path for internal users.",
      "remediation": "Remove the ManageInternalUsers permission from the permission set or replace it with a more restrictive permission that aligns with the clerk’s actual responsibilities."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive ViewAllData permission",
      "severity": "High",
      "file": "Report_Viewer_Plus.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ViewAllData, allowing users to view all records in the org, which exceeds the intended scope of viewing only specific reports.",
      "remediation": "Remove the ViewAllData permission from the permission set and rely on object-level read permissions and RunReports/ExportReport permissions to restrict access."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Class runs without sharing",
      "severity": "High",
      "file": "ContactSearchController.cls",
      "lines": "1-10",
      "explanation": "The class is declared 'without sharing', so it ignores record‑level sharing rules. Because the class is exposed to a Guest User profile, any guest can read all matching Contact records regardless of sharing.",
      "remediation": "Change the class declaration to 'with sharing' or 'inherited sharing', or add a WITH USER_MODE clause to the SOQL to enforce sharing."
    },
    {
      "category": "C5",
      "title": "Guest user can access Apex method and read Contact data",
      "severity": "High",
      "file": "Partner Site Profile.profile-meta.xml",
      "lines": "entire file",
      "explanation": "The Guest User profile grants access to the ContactSearchController Apex class and read permissions on Contact. This allows unauthenticated users to call the method and retrieve potentially sensitive contact information.",
      "remediation": "Remove Apex class access from the Guest User profile, restrict the method to authenticated users, or enforce stricter field‑level and sharing controls."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C5",
      "title": "Guest User Data Creation",
      "severity": "High",
      "file": "EventRegistrationController.cls",
      "lines": "registerForEvent method",
      "explanation": "The @AuraEnabled method is exposed to guest users via the profile, allowing unauthenticated visitors to create EventRegistration__c records, leading to data modification and potential spam or abuse.",
      "remediation": "Restrict the Apex class access to authenticated users only, or add a check for user identity and enforce a permission set that limits creation. Alternatively, remove the class from the guest profile and implement a custom site guest user permission set that does not allow create on EventRegistration__c."
    }
  ]
}
